
.character-block {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.line-main {
  display: flex;
  align-items: baseline;
  gap: 8px;
  white-space: nowrap;
}

.name {
  color: var(--c-text);
  font-size: 12px;
}

.stage {
  font-size: 11px;
}

.value {
  color: var(--c-text-muted);
  font-size: 11px;
}

.line-voice {
  color: var(--c-text-muted);
  font-style: italic;
  font-size: 11px;
  padding-left: 1em;
  word-break: break-word;
}
